  const submitHint=document.querySelector('.submit-panel p'),submitHintText=submitHint?submitHint.textContent:'';let inlineConfirmed=false;
  function resetInlineConfirm(){if(!inlineConfirmed)return;inlineConfirmed=false;if(submitHint)submitHint.textContent=submitHintText;button.textContent='Nộp bài';}
  form.addEventListener('input',()=>{resetInlineConfirm();if(attempt.status!=='in-progress')return;attempt.answers=readAnswers();save();progress();});
  form.addEventListener('change',()=>{if(attempt.status!=='in-progress')return;attempt.answers=readAnswers();save();progress();});
  if(nameInput&&!nameInput.value.trim()&&scorm.studentName)nameInput.value=scorm.studentName.slice(0,80);
